const payload = $input.first().json || {};

// =======================
// Normalize input
// =======================

let request = payload.request || {};
let response = payload.response || {};
let reply = payload.reply || response.reply || {};

// إذا الـ payload نفسه هو request
if ((!request || Object.keys(request).length === 0) && payload.meta) {
  request = payload;
}

// إذا response جاي مباشرة بشكل reply
if (!reply.text && response.text) {
  reply = response;
}

// =======================
// Resolve chat_id
// =======================

const chatId =
  payload?.chat_id ||
  payload?.chatId ||
  payload?.meta?.chat_id ||
  payload?.user?.channel_user_id ||
  payload?.user?.telegram_id ||
  payload?.channel_chat_id ||

  request?.chat_id ||
  request?.chatId ||
  request?.meta?.chat_id ||
  request?.user?.channel_user_id ||
  request?.user?.telegram_id ||
  request?.channel_chat_id ||

  response?.chat_id ||
  response?.meta?.chat_id ||

  payload?.analysis?.chatId ||
  payload?.analysis?.chat_id;

if (!chatId) {
  throw new Error(
    "Missing Telegram chat_id. Current input keys: " +
    Object.keys(payload).join(", ") +
    " | payload.user=" +
    JSON.stringify(payload.user || {}) +
    " | request.user=" +
    JSON.stringify(request.user || {})
  );
}

// =======================
// Resolve reply
// =======================

if (!reply || Object.keys(reply).length === 0) {
  reply = {
    type: "text",
    text: payload.error
      ? `حدث خطأ: ${payload.error}`
      : "تم."
  };
}

// =======================
// Build buttons
// =======================

const buttons = Array.isArray(reply.buttons) ? reply.buttons : [];

const inlineKeyboard = buttons
  .filter(button => button && button.label && button.action)
  .map(button => [
    {
      text: String(button.label),
      callback_data: String(button.action)
    }
  ]);

// دعم keyboard الجاهز إذا جاي من WF_01
const directKeyboard = Array.isArray(reply.keyboard)
  ? reply.keyboard
  : [];

// =======================
// Build Telegram body
// =======================

const body = {
  chat_id: String(chatId),
  text: reply.text || "تم.",
  disable_web_page_preview: true
};

if (reply.parse_mode) {
  body.parse_mode = reply.parse_mode;
}

if (directKeyboard.length > 0) {
  body.reply_markup = {
    inline_keyboard: directKeyboard
  };
} else if (inlineKeyboard.length > 0) {
  body.reply_markup = {
    inline_keyboard: inlineKeyboard
  };
}

// =======================
// Return
// =======================

return [
  {
    json: {
      request,
      response,
      reply,
      body,
      payload: body
    }
  }
];

